#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define N 6
#define MAX_Q (N * N)

static const char grid[N][N] = {
    {'.', '.', '.', '.', '.', '.'},
    {'.', '.', '.', '.', '.', '.'},
    {'.', '.', '.', '.', '.', '.'},
    {'.', '.', '.', '.', '.', '.'},
    {'.', '.', '.', '.', '.', '.'},
    {'.', '.', '.', '.', '.', '.'}
};

static int q_row[MAX_Q];
static int q_col[MAX_Q];
static int visited[N][N];
static int dist[N][N];
static const int dr[4] = { -1, 1, 0, 0 };
static const int dc[4] = {  0, 0,-1, 1 };

int main(int argc, char **argv)
{
    if (argc != 5) {
        puts("INVALID_CELL");
        return 0;
    }
    int sr = strtol(argv[1], NULL, 10);
    int sc = strtol(argv[2], NULL, 10);
    int tr = strtol(argv[3], NULL, 10);
    int tc = strtol(argv[4], NULL, 10);
    if (sr < 0 || sr >= N || sc < 0 || sc >= N || tr < 0 || tr >= N || tc < 0 || tc >= N) {
        puts("INVALID_CELL");
        return 0;
    }
    int head = 0, tail = 0;
    q_row[tail] = sr;
    q_col[tail] = sc;
    tail++;
    visited[sr][sc] = 1;
    dist[sr][sc] = 0;
    bool reached = false;
    while (head < tail) {
        int r = q_row[head];
        int c = q_col[head];
        head++;
        if (r == tr && c == tc) { reached = true; break; }
        for (int d = 0; d < 4; ++d) {
            int nr = r + dr[d];
            int nc = c + dc[d];
            if (nr < 0 || nr >= N || nc < 0 || nc >= N) continue;
            if (grid[nr][nc] == '#') continue;
            if (visited[nr][nc]) continue;
            visited[nr][nc] = 1;
            dist[nr][nc] = dist[r][c] + 1;
            q_row[tail] = nr;
            q_col[tail] = nc;
            ++tail;
        }
    }
    if (reached) {
        printf("dist=%d\n", dist[tr][tc]);
    } else {
        puts("UNREACHABLE");
    }
    return 0;
}
